        return 1

    def __exit__(self, exc_type: object, exc: object, traceback: object) -> None:
        pass


class NestedContext:
    def __enter__(self) -> IntegerContext:
        return IntegerContext()

    def __exit__(self, exc_type: object, exc: object, traceback: object) -> None:
        pass


def read_nested() -> int:
    with NestedContext() as inner, inner as value:
        pass
    return value

